/* ==========================================================================
   Mobile Bottom Navigation â€” Premium App-Like Redesign
   ========================================================================== */

@media (max-width: 991.98px) {
    body:not(.elementor-template-canvas) {
        padding-bottom: calc(72px + env(safe-area-inset-bottom)) !important;
    }
}

/* Nav Bar Shell */
.wds-mobile-nav {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    background: rgba(255, 255, 255, 0.96);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-top: 1px solid rgba(0, 0, 0, 0.06);
    padding-bottom: env(safe-area-inset-bottom);
    border-radius: 0;
}

/* Nav Container */
.mobile-nav-container {
    display: flex;
    justify-content: space-around;
    align-items: stretch;
    height: 62px;
    padding: 0 4px;
}

/* â”€â”€ Regular Nav Item â”€â”€ */
.mnav-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    flex: 1;
    text-decoration: none !important;
    color: #b0bac4;
    padding: 8px 4px 6px;
    position: relative;
    transition: color 0.2s ease;
    -webkit-tap-highlight-color: transparent;
}

.mnav-icon-wrap {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 28px;
    border-radius: 20px;
    background: transparent;
    transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.mnav-item i {
    font-size: 22px;
    line-height: 1;
    transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
    display: block;
}

.mnav-label {
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.01em;
    transition: all 0.2s ease;
    line-height: 1;
}

/* Active State */
.mnav-item.is-active {
    color: #485349;
}

.mnav-item.is-active .mnav-icon-wrap {
    background: rgba(72, 83, 73, 0.08);
    transform: scale(1.08);
}

.mnav-item.is-active i {
    transform: scale(1.05);
}

/* Tap feedback */
.mnav-item:active .mnav-icon-wrap {
    transform: scale(0.92);
    background: rgba(72, 83, 73, 0.06);
}

/* â”€â”€ Center FAB â”€â”€ */
.mnav-center {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    gap: 4px;
    flex: 1;
    text-decoration: none !important;
    color: #b0bac4;
    padding-bottom: 6px;
    position: relative;
    -webkit-tap-highlight-color: transparent;
}

.mnav-fab {
    position: absolute;
    top: -14px;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: linear-gradient(135deg, #fac273 0%, #e2a03f 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: none;
    border: 3px solid #ffffff;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    color: #485349;
}

.mnav-fab i {
    font-size: 22px;
    line-height: 1;
    color: #485349;
    display: block;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}



.mnav-center:hover .mnav-fab,
.mnav-center.is-active .mnav-fab {
    transform: translateY(-4px) scale(1.08);
    box-shadow: none;
}

.mnav-center.is-active .mnav-fab {
    background: linear-gradient(135deg, #e2a03f 0%, #c8882a 100%);
}

.mnav-center.is-active .mnav-fab::before {
    border-color: rgba(250, 194, 115, 0.35);
    inset: -7px;
}

.mnav-center:active .mnav-fab {
    transform: scale(0.92);
}

.mnav-center .mnav-label {
    margin-top: 24px;
    font-size: 10px;
    font-weight: 600;
    color: #b0bac4;
    letter-spacing: 0.01em;
}

.mnav-center.is-active .mnav-label {
    color: #e2a03f;
}

/* Mobile Scrollable Filter Tabs & Squish Fixes */
.filter-tabs {
    display: flex !important;
    flex-wrap: nowrap !important;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch;
    width: 100% !important;
}

.filter-tabs::-webkit-scrollbar {
    display: none !important; /* Hide scrollbar */
}

.filter-tabs {
    -ms-overflow-style: none;  /* IE and Edge */
    scrollbar-width: none;  /* Firefox */
}

.btn-filter-tab {
    flex-shrink: 0 !important;
}

/* Hide Sidebar / Drawer on Mobile Viewports */
@media (max-width: 991.98px) {
    #kt_aside, 
    #kt_aside_toggle,
    .aside,
    [data-kt-drawer-name="aside"] {
        display: none !important;
