}

.btn-filter-tab .status-dot.bg-success {
    background: #22c55e !important;
}

/* ── Controls Group ── */
.card-header-filter-v3 .filter-controls {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
    margin-left: auto;
    padding-left: 4px;
}

/* Divider between tabs and controls */
.card-header-filter-v3 .filter-divider {
    width: 1px;
    height: 22px;
    background: #e2e8f0;
    flex-shrink: 0;
}

/* Search form */
.card-header-filter-v3 .search-form-wrap {
    position: relative;
    flex-shrink: 0;
}

.card-header-filter-v3 .search-form-wrap .search-icon {
    position: absolute;
    left: 11px;
    top: 50%;
    transform: translateY(-50%);
    color: #94a3b8;
    font-size: 14px;
    pointer-events: none;
    z-index: 1;
}

.search-input-v3 {
    height: 36px;
    width: 170px;
    padding: 0 12px 0 32px;
    border: 1px solid #e2e8f0;
    border-radius: 999px;
    font-size: 12.5px;
    color: #334155;
    background: #ffffff;
    outline: none;
    transition: border-color 0.2s ease;
    font-family: 'Plus Jakarta Sans', sans-serif;
}

.search-input-v3::placeholder {
    color: #94a3b8;
}

.search-input-v3:focus {
    border-color: #fac273;
}

/* Filter icon button */
.btn-filter-icon-v3 {
    width: 36px;
    height: 36px;
    border-radius: 9px;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #64748b;
    font-size: 17px;
    cursor: pointer;
    transition: all 0.18s ease;
    padding: 0;
}

.btn-filter-icon-v3:hover {
    background: #f8fafc;
    border-color: #cbd5e1;
    color: #334155;
}

.btn-filter-icon-v3.border-warning {
    border-color: #fac273;
    color: #e2a03f;
}

/* Sort button */
.btn-sort-v3 {
    height: 36px;
    padding: 0 12px;
    border-radius: 10px;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 600;
    color: #334155;
    cursor: pointer;
    transition: all 0.18s ease;
    white-space: nowrap;
    font-family: 'Plus Jakarta Sans', sans-serif;
}

.btn-sort-v3:hover {
    background: #f8fafc;
    border-color: #cbd5e1;
}

/* ── Mobile: Split into 2 rows (tabs & controls) ── */
@media (max-width: 991.98px) {
    .card-header-filter-v3 {
        flex-direction: column;
        align-items: stretch;
        gap: 12px;
    }
    
    .card-header-filter-v3 .filter-divider {
        display: none;
    }
    
