    padding: 20px 22px 16px;
}

/* ── Category Tabs ── */
.create-cat-tabs {
    display: flex;
    gap: 10px;
    flex-wrap: nowrap;
    overflow-x: auto;
    list-style: none;
    margin: 0 0 4px;
    padding: 0 0 6px;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.create-cat-tabs::-webkit-scrollbar { display: none; }

.create-cat-tab-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 12px 14px;
    border-radius: 12px;
    background: #f8fafc;
    border: 1px solid #f1f5f9;
    cursor: pointer;
    text-decoration: none !important;
    color: #64748b;
    font-size: 12px;
    font-weight: 600;
    transition: all 0.18s ease;
    white-space: nowrap;
    min-width: 80px;
}

.create-cat-tab-item:hover {
    background: #f1f5f9;
    color: #1e293b;
}

.create-cat-tab-item.active {
    background: #fac273;
    border-color: #fac273;
    color: #485349;
}

/* ── Sub-section separator ── */
.create-sub-separator {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 14px 0 8px;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #94a3b8;
}

.create-sub-separator::before,
.create-sub-separator::after {
    content: '';
    flex: 1;
    height: 1px;
    background: #f1f5f9;
}

/* ── Subtags / subtheme pills ── */
.create-subtabs {
    display: flex;
    gap: 8px;
    flex-wrap: nowrap;
    overflow-x: auto;
    list-style: none;
    margin: 0;
    padding: 0 0 4px;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.create-subtabs::-webkit-scrollbar { display: none; }

.create-subtab-item {
    display: inline-flex;
    align-items: center;
    padding: 5px 14px;
    border-radius: 999px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    white-space: nowrap;
    cursor: pointer;
    text-decoration: none !important;
    transition: all 0.18s ease;
}

.create-subtab-item:hover {
    background: #f1f5f9;
    color: #1e293b;
}

.create-subtab-item.active {
    background: rgba(72, 83, 73, 0.08);
    border-color: #485349;
    color: #485349;
    font-weight: 700;
}

/* ── Divider ── */
.create-divider {
    height: 1px;
    background: #f1f5f9;
    margin: 16px 0;
}

/* ── Search & Sort row ── */
.create-search-row {
    display: flex;
    align-items: center;
    gap: 10px;
}

.create-search-form {
    position: relative;
    flex: 1;
    max-width: 300px;
}

.create-search-icon {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: #94a3b8;
    font-size: 15px;
    pointer-events: none;
}

.create-search-input {
    width: 100%;
    height: 38px;
    padding: 0 14px 0 36px;
    border: 1px solid #e2e8f0;
    border-radius: 999px;
    font-size: 13px;
    color: #334155;
    background: #f8fafc;
    outline: none;
    font-family: 'Plus Jakarta Sans', sans-serif;
    transition: border-color 0.2s;
}

.create-search-input:focus {
    border-color: #fac273;
    background: #ffffff;
}

.create-sort-wrap {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 0 12px;
    height: 38px;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    background: #f8fafc;
    flex-shrink: 0;
}

.create-sort-icon {
    font-size: 15px;
    color: #94a3b8;
    flex-shrink: 0;
}

.create-sort-select {
    border: none;
    background: transparent;
    font-size: 13px;
    font-weight: 600;
    color: #334155;
    outline: none;
    font-family: 'Plus Jakarta Sans', sans-serif;
    cursor: pointer;
}

/* ── Theme Grid ── */
.create-theme-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 18px;
    margin-top: 8px;
    margin-bottom: 8px;
}

/* Skeleton placeholders */
.create-theme-card-placeholder {
    background: #ffffff;
    border: 1px solid #f1f5f9;
    border-radius: 16px;
    overflow: hidden;
}

/* ── Modal ── */
.create-modal-content {
    border: none;
    border-radius: 20px;
    overflow: hidden;
}

.create-modal-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    padding: 24px 24px 0;
    gap: 12px;
}

.create-modal-title {
    font-size: 1.1rem;
    font-weight: 800;
    color: #0f172a;
    margin: 0 0 4px;
}

.create-modal-subtitle {
    font-size: 12.5px;
    color: #94a3b8;
    margin: 0;
}

.create-modal-close {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    background: #ffffff;
    color: #64748b;
    font-size: 16px;
    cursor: pointer;
    flex-shrink: 0;
    transition: all 0.18s;
}

.create-modal-close:hover {
    background: #f1f5f9;
    color: #1e293b;
}

.create-modal-body {
    padding: 20px 24px;
    display: flex;
    flex-direction: column;
    gap: 18px;
}

/* Form field */
.create-field {
    display: flex;
    flex-direction: column;
    gap: 7px;
}

.create-label {
    font-size: 13px;
    font-weight: 700;
    color: #334155;
}

.create-label.required::after {
    content: ' *';
    color: #ef4444;
}

.create-input {
    height: 42px;
    padding: 0 14px;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    font-size: 13.5px;
    color: #1e293b;
    background: #f8fafc;
    outline: none;
    font-family: 'Plus Jakarta Sans', sans-serif;
    transition: border-color 0.2s, background 0.2s;
    width: 100%;
}

.create-input:focus {
    border-color: #fac273;
    background: #ffffff;
}

.create-input-group {
    display: flex;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    overflow: hidden;
    background: #f8fafc;
    transition: border-color 0.2s;
}

.create-input-group:focus-within {
    border-color: #fac273;
}

.create-input-prefix {
    padding: 0 12px;
    display: flex;
    align-items: center;
    font-size: 12px;
    color: #94a3b8;
    background: #f1f5f9;
    font-weight: 500;
    white-space: nowrap;
    flex-shrink: 0;
}

.create-input-suffix {
    border: none !important;
    border-radius: 0 !important;
    background: transparent !important;
    flex: 1;
}

.create-input-suffix:focus {
    background: transparent !important;
}

.create-field-hint {
    font-size: 11.5px;
    color: #94a3b8;
    font-weight: 500;
}

/* Modal footer */
.create-modal-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    padding: 0 24px 22px;
}

.create-btn-cancel {
    height: 40px;
    padding: 0 18px;
    border-radius: 10px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    color: #475569;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    font-family: 'Plus Jakarta Sans', sans-serif;
    transition: all 0.18s;
}

.create-btn-cancel:hover {
    background: #f1f5f9;
    border-color: #cbd5e1;
}

.create-btn-submit {
    height: 40px;
    padding: 0 20px;
    border-radius: 10px;
    background: #fac273;
    border: none;
    color: #485349;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    font-family: 'Plus Jakarta Sans', sans-serif;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    transition: all 0.18s;
}

.create-btn-submit:hover {
    background: #e2a03f;
}

/* Preview close button */
.create-preview-close {
    position: absolute;
    top: 12px;
    right: 12px;
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: rgba(255,255,255,0.9);
    border: none;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    color: #1e293b;
    cursor: pointer;
    z-index: 99;
    transition: background 0.18s;
}

.create-preview-close:hover {
    background: #ffffff;
}

/* ── Responsive ── */
@media (max-width: 1199px) {
    .create-theme-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 767px) {
    .create-theme-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
    }

    .create-filter-panel {
        padding: 16px;
        border-radius: 14px;
    }

    .create-search-form {
        max-width: none;
    }
}


/* ==========================================================================
   Create Page — Theme Card Overrides (JS-generated cards)
   ========================================================================== */

/* Style the JS-rendered cards inside #cardThemeContainer */
#cardThemeContainer .card,
#cardThemeContainer .inv-card-create {
    border: 1px solid #f1f5f9 !important;
    border-radius: 16px !important;
    overflow: hidden !important;
    box-shadow: none !important;
    transition: border-color 0.18s ease, transform 0.18s ease !important;
}

#cardThemeContainer .card:hover,
#cardThemeContainer .inv-card-create:hover {
    border-color: #e2e8f0 !important;
    transform: translateY(-2px) !important;
}

/* Remove create-theme-grid from #cardThemeContainer — use Bootstrap row */
#cardThemeContainer {
    display: flex !important;
    flex-wrap: wrap !important;
}


/* ==========================================================================
   Invitation Table Layout — Desktop Redesign
   ========================================================================== */

/* Container */
.inv-table-wrap {
    background: #ffffff;
    border: 1px solid #f1f5f9;
    border-radius: 16px;
    overflow: hidden;
    overflow-x: auto;
}

/* Table */
#invitation_table.se-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 600px;
}

/* Header */
#invitation_table.se-table thead tr {
    background: #fafbfc;
}

#invitation_table.se-table th {
    padding: 12px 18px;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: #94a3b8;
    border-bottom: 1px solid #f1f5f9;
    white-space: nowrap;
}

/* Body rows */
#invitation_table.se-table tbody tr {
    border-bottom: 1px solid #f8fafc;
    transition: background 0.15s ease;
}

#invitation_table.se-table tbody tr:last-child {
    border-bottom: none;
}

#invitation_table.se-table tbody tr:hover {
    background: rgba(250, 194, 115, 0.04);
}

#invitation_table.se-table td {
    padding: 14px 18px;
    vertical-align: middle;
    font-size: 13px;
    color: #475569;
}

/* ── Thumbnail ── */
.inv-table-thumb {
    display: block;
    width: 48px;
    height: 48px;
    border-radius: 10px;
    overflow: hidden;
    flex-shrink: 0;
    border: 1px solid #f1f5f9;
    text-decoration: none !important;
    background: #f8fafc;
}

.inv-table-thumb img,
.inv-table-thumb-plain img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.inv-table-thumb-plain {
    display: block;
    width: 48px;
    height: 48px;
    border-radius: 10px;
    overflow: hidden;
    flex-shrink: 0;
    border: 1px solid #f1f5f9;
    opacity: 0.5;
    background: #f8fafc;
}

/* ── Title ── */
.inv-table-title {
    font-size: 13.5px;
    font-weight: 700;
    color: #1e293b;
    text-decoration: none !important;
    transition: color 0.15s ease;
    line-height: 1.3;
    display: block;
    max-width: 220px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

a.inv-table-title:hover {
    color: #e2a03f;
}

span.inv-table-title {
    color: #94a3b8;
}

/* ── Stat numbers in table ── */
#invitation_table .fw-bold.text-gray-700 {
    font-size: 13.5px !important;
    font-weight: 700 !important;
    color: #1e293b !important;
}

/* ── Status badges ── */
.se-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.02em;
    white-space: nowrap;
}

.se-badge-success { background: #dcfce7; color: #16a34a; }
.se-badge-warning { background: #fef9c3; color: #a16207; }
.se-badge-info    { background: #e0f2fe; color: #0369a1; }
.se-badge-danger  { background: #fee2e2; color: #dc2626; }

/* ── Action buttons ── */
.se-btn-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    height: 32px;
    padding: 0 12px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 700;
    text-decoration: none !important;
    transition: all 0.15s ease;
    cursor: pointer;
    border: none;
    white-space: nowrap;
}

.se-btn-primary {
    background: #fac273;
    color: #485349 !important;
}
.se-btn-primary:hover {
    background: #e2a03f;
    color: #485349 !important;
}

.se-btn-secondary {
    background: #f8fafc;
    color: #475569 !important;
    border: 1px solid #e2e8f0;
}
.se-btn-secondary:hover {
    background: #f1f5f9;
    color: #1e293b !important;
    border-color: #cbd5e1;
}

/* ── Dropdown button (Actions menu trigger) ── */
#invitation_table .btn.btn-light.btn-sm {
    height: 32px !important;
    padding: 0 12px !important;
    border-radius: 8px !important;
    font-size: 12px !important;
    font-weight: 700 !important;
    background: #f8fafc !important;
    border: 1px solid #e2e8f0 !important;
    color: #475569 !important;
    display: inline-flex !important;
    align-items: center !important;
    gap: 5px !important;
    transition: all 0.15s ease !important;
}

#invitation_table .btn.btn-light.btn-sm:hover {
    background: #f1f5f9 !important;
    border-color: #cbd5e1 !important;
    color: #1e293b !important;
}

/* ── Mobile: stack table rows ── */
@media (max-width: 767px) {
    .inv-table-wrap {
        border-radius: 12px;
    }

    #invitation_table.se-table th {
        padding: 10px 12px;
    }

    #invitation_table.se-table td {
        padding: 10px 12px;
    }

    .inv-table-title {
        max-width: 140px;
    }
}


/* ==========================================================================
   Table Layout — Force overrides (neutralize Bootstrap/KT conflicts)
   ========================================================================== */

/* Remove table-hover background from Bootstrap */
#invitation_table.table-hover > tbody > tr:hover > * {
    background-color: rgba(250, 194, 115, 0.04) !important;
    color: inherit !important;
}

/* Force thumbnail span to display as block (not inline) */
#invitation_table .inv-table-thumb-plain {
    display: inline-block !important;
}

/* Visitor & RSVP number columns */
#invitation_table td.text-center.fw-bold {
    font-size: 14px !important;
    font-weight: 700 !important;
    color: #0f172a !important;
    letter-spacing: -0.01em;
}

/* Tighten actions column — no wrapping */
#invitation_table td.text-end {
    white-space: nowrap !important;
}

/* Empty state inside table */
#invitation_table td[colspan] {
    padding: 48px 20px !important;
    color: #94a3b8 !important;
    font-size: 13px !important;
}

#invitation_table td[colspan] i {
    font-size: 40px !important;
    display: block !important;
    opacity: 0.2 !important;
    margin-bottom: 10px !important;
}


/* ==========================================================================
   Account Settings Page (.stg-*)
   ========================================================================== */

/* ── Settings Card ── */
.stg-card {
    background: #ffffff;
    border: 1px solid #f1f5f9;
    border-radius: 18px;
    overflow: hidden;
}

/* Card Header (collapsible trigger) */
.stg-card-header {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 18px 22px;
    cursor: pointer;
    user-select: none;
    transition: background 0.15s ease;
}

.stg-card-header:hover {
    background: #fafbfc;
}

.stg-card-icon-wrap {
    width: 42px;
    height: 42px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    flex-shrink: 0;
}

.stg-card-header-text {
    flex: 1;
    min-width: 0;
}

.stg-card-header-title {
    font-size: 14px;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.stg-card-header-sub {
    font-size: 12px;
    color: #94a3b8;
    margin-top: 2px;
    font-weight: 500;
}

.stg-card-caret {
    font-size: 15px;
    color: #cbd5e1;
    flex-shrink: 0;
    transition: transform 0.2s ease;
}

