.stg-card-header[aria-expanded="false"] .stg-card-caret {
    transform: rotate(-90deg);
}

/* Card body */
.stg-card-body {
    padding: 6px 22px 20px;
    border-top: 1px solid #f8fafc;
    display: flex;
    flex-direction: column;
    gap: 18px;
}

/* Card footer */
.stg-card-footer {
    padding: 14px 22px 18px;
    display: flex;
    justify-content: flex-end;
    border-top: 1px solid #f8fafc;
}

/* ── Form Fields ── */
.stg-field {
    display: flex;
    flex-direction: column;
    gap: 7px;
}

.stg-label {
    font-size: 13px;
    font-weight: 700;
    color: #334155;
}

.stg-label.required::after {
    content: ' *';
    color: #ef4444;
}

