    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    font-family: 'Plus Jakarta Sans', sans-serif;
    transition: background 0.18s ease;
}

.stg-btn-save:hover {
    background: #e2a03f;
}

.stg-btn-save-sm {
    height: 36px;
    font-size: 12.5px;
    padding: 0 16px;
}

/* Change button */
.stg-btn-change {
    height: 34px;
    padding: 0 14px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    background: #f8fafc;
    color: #475569;
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    font-family: 'Plus Jakarta Sans', sans-serif;
    white-space: nowrap;
    transition: all 0.15s ease;
}

.stg-btn-change:hover {
    background: #f1f5f9;
    border-color: #cbd5e1;
    color: #1e293b;
}

/* Cancel button */
.stg-btn-cancel {
    height: 36px;
    padding: 0 14px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    background: #f8fafc;
    color: #64748b;
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    font-family: 'Plus Jakarta Sans', sans-serif;
    transition: all 0.15s ease;
}

.stg-btn-cancel:hover {
    background: #f1f5f9;
}

/* ── Security Rows (email / password) ── */
.stg-security-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 14px 0;
