/* ==========================================================================
   Kekondangan Luxury Botanical Front Page (.kk-*) - Flat Clean Branding
   ========================================================================== */

body.kk-front-body {
    background-color: #2b332f !important;
    color: #ffffff !important;
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    margin: 0 !important;
    padding: 0 !important;
    min-height: 100vh;
    overflow-x: hidden;
}

.kk-page-wrapper {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
    background-color: #2b332f !important;
    background: #2b332f !important;
}

.kk-botanical-bg {
    display: none !important;
}

/* ── Container ── */
.kk-container {
    width: 100%;
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 28px;
    box-sizing: border-box;
}

/* ── Header ── */
.kk-header {
    padding: 26px 0 16px;
    position: relative;
    z-index: 30;
}

.kk-header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.kk-brand-logo {
    display: flex;
    align-items: center;
    gap: 12px;
    text-decoration: none !important;
}

.kk-logo-img {
    height: 48px;
    width: auto;
    display: block;
    object-fit: contain;
    filter: none !important;
    box-shadow: none !important;
}

.kk-logo-icon {
    flex-shrink: 0;
}

.kk-brand-name {
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 24px;
    font-weight: 800;
    color: #ffffff;
    letter-spacing: -0.03em;
}

.kk-help-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 22px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.18);
    color: #ffffff !important;
    font-size: 13.5px;
    font-weight: 600;
    text-decoration: none !important;
    transition: all 0.2s ease;
    box-shadow: none !important;
}

.kk-help-btn i,
.kk-help-btn svg {
    font-size: 16px;
    width: 16px;
    height: 16px;
    color: #fac273;
    fill: #fac273;
    flex-shrink: 0;
}

.kk-help-btn:hover {
    background: rgba(250, 194, 115, 0.15);
    border-color: #fac273;
    color: #fac273 !important;
    box-shadow: none !important;
}

/* ── Hero Section ── */
.kk-hero-section {
    flex: 1;
    display: flex;
    align-items: center;
    position: relative;
    padding: 10px 0 50px;
    z-index: 10;
}

.kk-hero-grid {
    display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    grid-template-rows: auto auto auto;
    grid-template-areas:
        "text    visual"
        "cta     visual"
        "features visual";
    column-gap: 48px;
    row-gap: 0;
    align-items: start;
    width: 100%;
}

.kk-hero-text     { grid-area: text; }
.kk-cta-desktop   { grid-area: cta; padding-top: 20px; padding-bottom: 20px; }
.kk-features-row  { grid-area: features; }
.kk-hero-visual   {
    grid-area: visual;
    display: flex;
    justify-content: center;
    align-items: center;
    align-self: stretch;
}
.kk-cta-mobile    { display: none; }

/* Tagline / Overline */
.kk-tagline-wrap {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.kk-tagline-line {
    width: 32px;
    height: 2px;
    background: #fac273;
    border-radius: 99px;
}

.kk-tagline-text {
    font-size: 11.5px;
    font-weight: 700;
    letter-spacing: 0.22em;
    color: #cfd8ce;
    text-transform: uppercase;
}

/* Headline */
.kk-hero-title {
    font-family: 'Cormorant Garamond', Georgia, 'Times New Roman', serif !important;
    font-size: 64px;
    line-height: 1.08;
    font-weight: 600;
    color: #ffffff !important;
    margin: 0 0 18px 0;
    letter-spacing: -0.015em;
    text-shadow: none !important;
}

.kk-hero-title span {
    color: #fac273;
    font-weight: 600;
}

/* Subtitle */
.kk-hero-subtitle {
    font-size: 16px;
    line-height: 1.6;
    color: #b5c3b4;
    max-width: 460px;
    margin: 0 0 0 0;
    font-weight: 400;
}

/* CTA Button */
.kk-hero-cta {
    margin-bottom: 0;
}

.kk-btn-primary {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 15px 32px;
    background: #fac273 !important;
    color: #2b332f !important;
    font-size: 15px;
    font-weight: 700;
    border-radius: 12px;
    text-decoration: none !important;
    box-shadow: none !important;
    border: none !important;
    transition: all 0.2s ease;
}

.kk-btn-primary i,
.kk-btn-primary svg {
    font-size: 17px;
    width: 17px;
    height: 17px;
    flex-shrink: 0;
    color: #2b332f !important;
    fill: #2b332f !important;
    transition: transform 0.2s ease;
}

.kk-btn-primary:hover {
    background: #f3b154 !important;
    color: #1a201c !important;
    box-shadow: none !important;
}

.kk-btn-primary:hover i,
.kk-btn-primary:hover svg {
    transform: translateX(4px);
}

/* ── 3 Value Proposition Features ── */
.kk-features-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    max-width: 100%;
}

.kk-feature-item {
    display: flex;
    align-items: flex-start;
    gap: 13px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
    padding: 16px 16px;
    box-shadow: none !important;
    transition: all 0.2s ease;
}

.kk-feature-item:hover {
    background: rgba(255, 255, 255, 0.07);
    border-color: rgba(250, 194, 115, 0.3);
}

.kk-feature-icon-box {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    background: rgba(250, 194, 115, 0.12);
    color: #fac273;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-shadow: none !important;
}

.kk-feature-icon-box svg {
    width: 20px;
    height: 20px;
    stroke: #fac273;
    color: #fac273;
}

.kk-feature-title {
    font-size: 13px;
    font-weight: 700;
    color: #ffffff;
    margin: 0 0 2px 0;
    line-height: 1.25;
}

.kk-feature-desc {
    font-size: 10.5px;
    color: #9cb09b;
    margin: 0;
    line-height: 1.35;
    font-weight: 400;
}

/* ── Right Visual ── */
.kk-hero-visual {
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
}

.kk-visual-wrapper {
    position: relative;
    width: 100%;
    max-width: 650px;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* Glow removed */
.kk-visual-glow {
    display: none !important;
}

.kk-hero-illustration {
    position: relative;
    z-index: 2;
    width: 100%;
    max-height: 650px;
    object-fit: contain;
    filter: none !important;
    box-shadow: none !important;
}

.kk-script-wrap {
    position: absolute;
    bottom: -10px;
    right: -20px;
    z-index: 3;
    text-align: right;
    transform: rotate(-6deg);
    pointer-events: none;
}

.kk-script-text {
    font-family: 'Alex Brush', cursive !important;
    font-size: 40px;
    color: #fac273 !important;
    line-height: 1.05;
    display: block;
    text-shadow: none !important;
    white-space: nowrap;
}

.kk-script-underline {
    display: block;
    margin-top: -3px;
    margin-left: auto;
    opacity: 0.9;
}

.kk-cta-desktop {
    display: block;
}
.kk-cta-mobile {
    display: none;
}

/* ==========================================================================
   404 Page Styles
   ========================================================================== */
.kk-404-header .kk-header-inner {
    justify-content: center;
}

.kk-404-section {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px 0 60px;
    text-align: center;
}

.kk-404-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    max-width: 600px;
    margin: 0 auto;
}

.kk-404-visual {
    margin-bottom: 24px;
    width: 100%;
}

.kk-404-illustration {
    max-width: 100%;
    max-height: 280px;
    object-fit: contain;
    display: block;
    margin: 0 auto;
}

.kk-404-section .kk-hero-title {
    font-size: 42px;
    margin-bottom: 12px;
    text-align: center;
}

.kk-404-subtitle {
    text-align: center;
    margin: 0 auto 32px;
}

.kk-404-actions {
    display: flex;
    justify-content: center;
}

/* ── Responsive Breakpoints ── */
@media (max-width: 1199.98px) {
    .kk-hero-title {
        font-size: 54px;
    }
    .kk-features-row {
        grid-template-columns: repeat(3, 1fr);
        gap: 10px;
    }
    .kk-feature-item {
        padding: 10px 10px;
    }
    .kk-script-text {
        font-size: 34px;
    }
}

@media (max-width: 991.98px) {

    /* Full viewport — fit di webview, scrollable di browser mobile */
    body.kk-front-body {
        min-height: 100svh;
        min-height: 100dvh;
        overflow-x: hidden;
        overflow-y: auto;
        padding-bottom: 0 !important;
    }
    .kk-page-wrapper {
        min-height: 100svh;
        min-height: 100dvh;
        display: flex;
        flex-direction: column;
        overflow-x: hidden;
    }
    .kk-container {
        padding: 0 16px;
    }

    /* Header */
    .kk-header {
        padding: 10px 0 6px;
        flex-shrink: 0;
    }
    .kk-brand-logo {
        gap: 7px;
    }
    .kk-logo-img {
        height: 28px;
    }
    .kk-brand-logo svg {
        width: 26px;
        height: 26px;
    }
    .kk-brand-name {
        font-size: 17px;
    }
    .kk-help-btn {
        padding: 5px 12px;
        font-size: 11.5px;
        gap: 5px;
        border-radius: 999px;
    }
    .kk-help-btn svg {
        width: 13px;
        height: 13px;
    }

    /* Hero section — isi sisa tinggi layar */
    .kk-hero-section {
        flex: 1;
        min-height: 0;
        padding: 4px 0 10px;
        display: flex;
        align-items: stretch;
        overflow: hidden;
    }
    .kk-hero-section .kk-container {
        display: flex;
        flex-direction: column;
        flex: 1;
        min-height: 0;
    }
    .kk-hero-grid {
        display: flex;
        flex-direction: column;
        flex: 1;
        min-height: 0;
        gap: 6px;
    }

    /* Mobile order: text → visual → features → CTA */
    .kk-hero-text    { order: 1; flex-shrink: 0; }
    .kk-hero-visual  { order: 2; flex: 1; min-height: 0; }
    .kk-features-row { order: 3; flex-shrink: 0; }
    .kk-cta-mobile   { order: 4; flex-shrink: 0; }
    .kk-cta-desktop  { display: none !important; }

    /* 1. Text Area */
    .kk-hero-text {
        text-align: left;
        width: 100%;
        margin-bottom: 0;
    }
    .kk-tagline-wrap {
        justify-content: flex-start;
        margin-bottom: 6px;
        gap: 8px;
    }
    .kk-tagline-line {
        width: 24px;
        height: 2px;
    }
    .kk-tagline-text {
        font-size: 10px;
        letter-spacing: 0.16em;
        color: #cfd8ce;
    }
    .kk-hero-title {
        font-family: 'Cormorant Garamond', Georgia, serif !important;
        font-size: clamp(24px, 7vw, 32px) !important;
        line-height: 1.1 !important;
        margin: 0 0 6px 0;
        text-align: left;
        letter-spacing: -0.01em;
    }
    .kk-hero-subtitle {
        font-size: clamp(11px, 3vw, 13px);
        line-height: 1.4;
        margin: 0;
        text-align: left;
        color: #b5c3b4;
        max-width: 100%;
    }

    /* 2. Illustration — flex mengisi sisa ruang secara otomatis */
    .kk-hero-visual {
        order: 2;
        width: 100%;
        flex: 1;
        min-height: 0;
        margin: 4px 0 8px;
        display: flex;
        justify-content: center;
        align-items: center;
        overflow: hidden;
    }

    .kk-visual-wrapper {
        width: 100%;
        height: 100%;
        max-width: 100%;
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .kk-hero-illustration {
        width: auto;
        height: 100%;
        max-width: 100%;
        object-fit: contain;
        display: block;
    }

    /* 3. Feature Cards */
    .kk-features-row {
        order: 3;
        display: flex !important;
        flex-direction: column !important;
        gap: 8px;
        width: 100%;
        margin: 0 0 12px 0;
    }
    .kk-feature-item {
        display: flex;
        flex-direction: row;
        align-items: center;
        text-align: left;
        gap: 14px;
        padding: 12px 16px;
        border-radius: 12px;
        background: rgba(255, 255, 255, 0.05);
        border: 1px solid rgba(255, 255, 255, 0.08);
        box-shadow: none !important;
    }
    .kk-feature-icon-box {
        width: 38px;
        height: 38px;
        border-radius: 9px;
        background: rgba(250, 194, 115, 0.12);
        color: #fac273;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }
    .kk-feature-icon-box svg {
        width: 20px;
        height: 20px;
        stroke: #fac273;
        color: #fac273;
    }
    .kk-feature-text {
        display: flex;
        flex-direction: column;
        gap: 2px;
    }
    .kk-feature-title {
        font-size: 13px;
        font-weight: 700;
        color: #ffffff;
        margin: 0;
        line-height: 1.2;
    }
    .kk-feature-desc {
        display: block !important;
        font-size: 11.5px;
        color: #9cb09b;
        margin: 0;
        line-height: 1.3;
        font-weight: 400;
    }

    /* 4. Bottom CTA Button */
    .kk-cta-mobile {
        order: 4;
        display: block !important;
        width: 100%;
        margin: 0 0 12px 0;
    }
    .kk-cta-mobile .kk-btn-primary {
        width: 100%;
        max-width: 100%;
        height: 48px;
        padding: 0 20px;
        font-size: 14.5px;
        font-weight: 700;
        border-radius: 12px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: #fac273 !important;
        color: #2b332f !important;
        box-shadow: none !important;
    }
}





